     4	public record Cell(int x, int y) {
     5	
     6	    /**
     7	     * The eight coordinates surrounding this cell on the infinite grid.
     8	     * Adjacency is the model's only topological knowledge.
     9	     */
    10	    public Set<Cell> neighbours() {
    11	        Set<Cell> neighbours = new HashSet<>();
    12	        for (int dx = -1; dx <= 1; dx++) {
    13	            for (int dy = -1; dy <= 1; dy++) {
    14	                boolean isSelf = dx == 0 && dy == 0;
    15	                if (!isSelf) {
    16	                    neighbours.add(new Cell(x + dx, y + dy));
    17	                }
    18	            }
    19	        }
    20	        return Set.copyOf(neighbours);
    21	    }
    22	}
