     1	import java.util.Set;
     2	import java.util.stream.Collectors;
     3	import java.util.stream.Stream;
     4	
     5	public final class GameOfLife {
     6	
     7	    private GameOfLife() {
     8	    }
     9	
    10	    public static Set<Cell> nextGeneration(Set<Cell> livingCells) {
    11	        return cellsThatCouldChange(livingCells).stream()
    12	                .filter(cell -> ConwayRules.isAliveNextGeneration(
    13	                        livingCells.contains(cell),
    14	                        livingNeighbourCount(cell, livingCells)))
    15	                .collect(Collectors.toUnmodifiableSet());
    16	    }
    17	
    18	    /**
    19	     * The colony that results from applying {@link #nextGeneration} the given
    20	     * number of times. Advancing by zero generations leaves the colony as it is.
    21	     */
    22	    public static Set<Cell> generationsAfter(Set<Cell> livingCells, int generations) {
    23	        Set<Cell> colony = livingCells;
    24	        for (int generation = 0; generation < generations; generation++) {
    25	            colony = nextGeneration(colony);
    26	        }
    27	        return colony;
    28	    }
    29	
    30	    private static Set<Cell> cellsThatCouldChange(Set<Cell> livingCells) {
    31	        return livingCells.stream()
    32	                .flatMap(cell -> Stream.concat(Stream.of(cell), cell.neighbours().stream()))
    33	                .collect(Collectors.toUnmodifiableSet());
    34	    }
    35	
    36	    private static int livingNeighbourCount(Cell cell, Set<Cell> livingCells) {
    37	        return (int) cell.neighbours().stream().filter(livingCells::contains).count();
    38	    }
    39	}
