     1	import com.fasterxml.jackson.databind.JsonNode;
     2	import com.fasterxml.jackson.databind.ObjectMapper;
     3	import com.fasterxml.jackson.databind.node.ArrayNode;
     4	import com.fasterxml.jackson.databind.node.ObjectNode;
     5	import java.io.IOException;
     6	import java.io.InputStream;
     7	import java.util.Comparator;
     8	import java.util.HashSet;
     9	import java.util.Set;
    10	
    11	/**
    12	 * Translates between the external JSON representation and the domain's cells.
    13	 * Sole owner of the wire format.
    14	 */
    15	public final class GameOfLifeJson {
    16	
    17	    private static final ObjectMapper JSON = new ObjectMapper();
    18	
    19	    /** The order cells appear in on the wire: by column, then by row within a column. */
    20	    private static final Comparator<Cell> WIRE_ORDER =
    21	            Comparator.comparingInt(Cell::x).thenComparingInt(Cell::y);
    22	
    23	    private GameOfLifeJson() {
    24	    }
    25	
    26	    public static GenerationRequest readRequest(InputStream source) throws IOException {
    27	        JsonNode request = JSON.readTree(source);
    28	        return new GenerationRequest(
    29	                readLivingCells(request.get("aliveCells")),
    30	                request.get("steps").asInt());
    31	    }
    32	
    33	    public static String writeColony(Set<Cell> livingCells) {
    34	        ObjectNode response = JSON.createObjectNode();
    35	        ArrayNode aliveCells = response.putArray("aliveCells");
    36	        livingCells.stream()
    37	                .sorted(WIRE_ORDER)
    38	                .forEach(cell -> aliveCells.addArray().add(cell.x()).add(cell.y()));
    39	        return response.toString();
    40	    }
    41	
    42	    private static Set<Cell> readLivingCells(JsonNode aliveCells) {
    43	        Set<Cell> livingCells = new HashSet<>();
    44	        for (JsonNode cell : aliveCells) {
    45	            livingCells.add(new Cell(cell.get(0).asInt(), cell.get(1).asInt()));
    46	        }
    47	        return livingCells;
    48	    }
    49	}
